// Kysely table typings. Every table uses text primary keys generated by the app
// (stable, URL-safe identifiers), ISO-8601 text timestamps, JSON stored as text
// and 0/1 integers for booleans, so the same SQL runs on SQLite and PostgreSQL.

type Text = string;
type Nullable<T> = T | null;
type Bool = number; // 0 | 1

export interface UsersTable {
  id: Text;
  email: Text;
  display_name: Nullable<Text>;
  password_hash: Text;
  created_at: Text;
  updated_at: Text;
}

export interface SessionsTable {
  id: Text; // sha256 of the cookie token
  user_id: Text;
  created_at: Text;
  last_seen_at: Text;
  expires_at: Text;
  user_agent: Nullable<Text>;
}

